
CREATE TABLE IF NOT EXISTS risk_control_matrix (
  id SERIAL PRIMARY KEY,
  "processId" INT,
  "processName" VARCHAR(200),
  "subProcess" VARCHAR(200),
  "businessObjective" TEXT,
  "riskName" VARCHAR(255) NOT NULL,
  "riskDescription" TEXT,
  "inherentRiskScore" VARCHAR(50),
  "controlName" VARCHAR(255) NOT NULL,
  "controlDescription" TEXT,
  "controlType" VARCHAR(50),
  "controlFrequency" VARCHAR(50),
  "controlAutomation" VARCHAR(50),
  "testProcedure" TEXT,
  "expectedEvidence" TEXT,
  "ownerDepartmentId" INT,
  "ownerTeam" VARCHAR(100),
  "createdAt" TIMESTAMP DEFAULT NOW(),
  "updatedAt" TIMESTAMP DEFAULT NOW()
);

TRUNCATE TABLE risk_control_matrix RESTART IDENTITY CASCADE;
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Cho vay Khách hàng Cá nhân', 'Thẩm định hồ sơ & Nguồn thu', 'Đảm bảo thẩm định chính xác khả năng trả nợ của khách hàng cá nhân', 'Hồ sơ pháp lý, thu nhập hoặc giấy tờ tài sản bảo đảm bị làm giả', 'Khách hàng sử dụng giấy tờ giả (sao kê ngân hàng giả, xác nhận lương khống, sổ đỏ giả) để vay vốn vượt quá khả năng trả nợ, dẫn đến nợ xấu.', 'High', 'Đối chiếu nguồn thu độc lập & Xác thực CCCD gắn chip', 'Yêu cầu sao kê tài khoản ngân hàng chính chủ qua mã QR/App ngân hàng, kiểm tra dữ liệu định danh VNeID, tra cứu CIC toàn diện trước khi trình phê duyệt.', 'Preventive', 'Hàng ngày', 'IT-Dependent Manual', 'Chọn mẫu 25 hồ sơ giải ngân trong kỳ; đối chiếu hồ sơ thu nhập với sao kê ngân hàng thực tế và báo cáo tra cứu CIC; kiểm tra tính hợp lệ của xác thực CCCD gắn chip.', 'Hồ sơ vay vốn, báo cáo tra cứu CIC thời điểm phê duyệt, sao kê tài khoản có xác thực điện tử, biên bản thẩm định thực tế.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Cho vay Khách hàng Cá nhân', 'Định giá Tài sản bảo đảm', 'Bảo toàn vốn vay thông qua giá trị thanh lý thực tế của TSBĐ', 'Định giá tài sản bảo đảm cao hơn giá trị thị trường thực tế', 'Cán bộ định giá thông đồng hoặc thiếu khảo sát thị trường dẫn đến nâng khống giá trị BĐS/phương tiện vận tải, tỷ lệ LTV thực tế vượt trần quy định.', 'High', 'Thẩm định giá độc lập & Kiểm soát trần giá theo dữ liệu thị trường', 'Áp dụng công ty định giá độc lập hoặc hội đồng định giá độc lập tuyến 2 đối với tài sản từ 3 tỷ đồng trở lên; đối chiếu cơ sở dữ liệu giá giao dịch thực tế của LPBank.', 'Preventive', 'Hàng ngày', 'Manual', 'Kiểm tra chứng thư thẩm định giá, đối chiếu đơn giá định giá với bảng giá đất địa phương và giá thị trường lân cận; khảo sát hiện trạng ngẫu nhiên 5 tài sản lớn.', 'Chứng thư thẩm định giá, biên bản khảo sát hiện trạng có ảnh chụp và tọa độ GPS, tờ trình phê duyệt giá.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Cho vay Khách hàng Cá nhân', 'Kiểm tra sau cho vay & Quản lý nợ', 'Phát hiện sớm dấu hiệu suy giảm khả năng trả nợ và sử dụng vốn sai mục đích', 'Không thực hiện hoặc kiểm tra sau vay hình thức, khách hàng dùng vốn sai mục đích', 'Khách hàng vay tiêu dùng/kinh doanh nhưng chuyển tiền sang đầu cơ bất động sản, chứng khoán hoặc trả nợ ngân hàng khác mà không bị phát hiện.', 'High', 'Hệ thống tự động cảnh báo hạn kiểm tra sau vay và đối chiếu chứng từ mục đích', 'Hệ thống Core/BPM tự động nhắc hạn kiểm tra sau vay định kỳ (30/60/90 ngày); yêu cầu tải lên hóa đơn GTGT, biên bản giao nhận và ảnh chụp phương án kinh doanh.', 'Detective', 'Hàng tháng', 'IT-Dependent Manual', 'Trích xuất danh sách các khoản vay giải ngân quá 30 ngày chưa có biên bản kiểm tra sau vay; kiểm tra tính hợp pháp, hợp lệ của hóa đơn trên trang tra cứu Tổng cục Thuế.', 'Biên bản kiểm tra sau vay, kết quả tra cứu hóa đơn điện tử cơ quan Thuế, ảnh chụp cơ sở kinh doanh/tài sản mua sắm.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Cấp Tín dụng Khách hàng Doanh nghiệp', 'Phân tích BCTC & Dòng tiền', 'Đánh giá năng lực tài chính và phương án kinh doanh khả thi của doanh nghiệp', 'Báo cáo tài chính bị chỉnh sửa số liệu, doanh thu ảo, che giấu công nợ', 'Doanh nghiệp nộp BCTC nội bộ có số liệu lợi nhuận khống, che giấu các khoản nợ vay tại các TCTD khác hoặc giao dịch vòng vo với các bên liên quan.', 'Critical', 'Đối chiếu BCTC nộp Thuế điện tử và tra cứu CIC nhóm khách hàng liên quan', 'Bắt buộc đối chiếu BCTC với tờ khai quyết toán thuế TNDN nộp qua eTax; tra cứu CIC toàn diện nhóm khách hàng liên quan và người đại diện theo pháp luật.', 'Preventive', 'Hàng ngày', 'Manual', 'Yêu cầu trích xuất BCTC trực tiếp từ trang eTax của doanh nghiệp; đối chiếu chỉ tiêu doanh thu, chi phí, nợ phải trả trên BCTC với hồ sơ vay và báo cáo CIC.', 'Báo cáo tài chính có chữ ký số/mã vạch thuế, báo cáo kiểm toán độc lập, bảng tra cứu CIC tập đoàn/nhóm liên quan.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Cấp Tín dụng Khách hàng Doanh nghiệp', 'Giải ngân & Quản lý giải ngân', 'Đảm bảo tiền vay được giải ngân đúng mục đích và điều kiện tín dụng', 'Giải ngân khi chưa đáp ứng đủ điều kiện tiên quyết hoặc thanh toán bên thụ hưởng không hợp pháp', 'Cán bộ tín dụng cho giải ngân khi chưa hoàn tất công chứng thế chấp, chưa mua bảo hiểm công trình, hoặc tiền vay chuyển vào tài khoản bên thụ hưởng có dấu hiệu rửa tiền/công ty ma.', 'Critical', 'Kiểm soát phê duyệt giải ngân 4 mắt (Maker - Checker) và phong tỏa vốn vay', 'Kiểm soát viên độc lập rà soát checklist điều kiện trước giải ngân; giải ngân chuyển khoản trực tiếp cho bên bán hàng hóa/dịch vụ theo hợp đồng kinh tế.', 'Preventive', 'Hàng ngày', 'Automated', 'Kiểm tra 100% hồ sơ giải ngân trên 10 tỷ đồng; đối chiếu chứng từ giải ngân với điều kiện phê duyệt trên thông báo tín dụng; xác minh tính pháp lý của bên thụ hưởng.', 'Phiếu giải ngân, ủy nhiệm chi, hợp đồng kinh tế, biên bản nghiệm thu/hóa đơn GTGT, biên lai đăng ký giao dịch bảo đảm.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Nghiệp vụ Kho quỹ & Quản lý tiền mặt', 'Tồn quỹ & Điều hòa tiền mặt', 'Đảm bảo an toàn tài sản tiền mặt và tuân thủ định mức tồn quỹ', 'Tồn quỹ tiền mặt vượt định mức bảo hiểm kho quỹ hoặc thất thoát tiền mặt', 'Chi nhánh giữ lượng tiền mặt vượt định mức được Tổng Giám đốc phê duyệt mà không điều chuyển về Hội sở, tăng rủi ro mất an toàn kho quỹ.', 'Medium', 'Giám sát tự động hạn mức tồn quỹ cuối ngày và kiểm kê kép (Dual Control)', 'Hệ thống Core Banking tự động cảnh báo tồn quỹ vượt trần cuối ngày; thực hiện kiểm kê quỹ hàng ngày có sự tham gia của Giám đốc, Kế toán trưởng, Thủ quỹ.', 'Detective', 'Hàng ngày', 'Automated', 'So sánh số dư tiền mặt trên sổ cái GL cuối ngày với biên bản kiểm kê quỹ và hạn mức bảo hiểm kho quỹ trong 3 tháng gần nhất.', 'Báo cáo số dư tiền mặt cuối ngày, biên bản kiểm kê quỹ tiền mặt, quyết định phê duyệt hạn mức tồn quỹ của Hội đồng/TGĐ.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Nghiệp vụ Kho quỹ & Quản lý tiền mặt', 'Tiếp quỹ ATM/CDM & Thu giữ tiền giả', 'Phát hiện tiền giả và đảm bảo tính chính xác khi tiếp quỹ máy ATM/CDM', 'Tiền giả lọt vào lưu thông hoặc chênh lệch tiền mặt khi tiếp quỹ ATM/CDM', 'Tiền mặt nạp vào ATM hoặc nhập từ khách hàng không được kiểm định kỹ, dẫn đến tiền giả lọt vào máy hoặc mất cân đối sổ sách tiếp quỹ.', 'High', 'Sử dụng máy đếm tiền kiểm định đạt chuẩn và quy trình kiểm đếm tiếp quỹ 2 người', '100% tiền mặt nạp ATM/CDM phải qua máy đếm có chức năng soi tiền giả đã cập nhật phần mềm mới nhất; niêm phong hộp tiền có chữ ký 2 cán bộ.', 'Preventive', 'Hàng ngày', 'IT-Dependent Manual', 'Kiểm tra nhật ký cập nhật phần mềm nhận diện tiền giả cho ATM/CDM; kiểm tra sổ theo dõi thu giữ tiền giả và báo cáo NHNN; đối chiếu nhật ký tiếp quỹ ATM với log máy.', 'Sổ theo dõi thu giữ tiền giả, biên bản tiếp quỹ ATM/CDM, báo cáo xử lý chênh lệch quỹ, biên bản bảo dưỡng thiết bị kho quỹ.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Dịch vụ Tiền gửi & Giao dịch Khách hàng', 'Tất toán sổ tiết kiệm & Rút tiền mặt', 'Bảo vệ quyền lợi tiền gửi khách hàng và ngăn ngừa rủi ro đạo đức của giao dịch viên', 'Rút tiền, chuyển nhượng hoặc tất toán sổ tiết kiệm không có sự đồng thuận của khách hàng', 'Giao dịch viên hoặc kiểm soát viên lợi dụng quyền hạn thực hiện lệnh giả, ký thay khách hàng để chiếm đoạt tiền gửi tiết kiệm.', 'Critical', 'Kiểm soát kép phê duyệt hạn mức, đối chiếu chữ ký và giám sát Camera', 'Mọi giao dịch rút tiền từ 50 triệu đồng trở lên phải có chữ ký kiểm soát viên; hệ thống tự động gửi tin nhắn SMS/OTP biến động số dư tức thời cho khách hàng.', 'Preventive', 'Hàng ngày', 'Automated', 'Chọn mẫu 30 giao dịch rút tiền mặt/tất toán tiết kiệm trên 200 triệu đồng; kiểm tra mẫu chữ ký trên chứng từ so với chữ ký đăng ký mẫu; trích xuất video camera tại quầy tại thời điểm ký chứng từ.', 'Giấy lĩnh tiền, sổ tiết kiệm có dấu đã tất toán, video camera quầy giao dịch, log gửi tin nhắn SMS thông báo số dư.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Dịch vụ Tiền gửi & Giao dịch Khách hàng', 'Mở tài khoản thanh toán & Định danh khách hàng', 'Tuân thủ quy định KYC/eKYC và phòng ngừa tài khoản rác/tài khoản lừa đảo', 'Mở tài khoản thanh toán bằng giấy tờ tùy thân giả mạo hoặc không tuân thủ sinh trắc học', 'Kẻ gian sử dụng CMND/CCCD giả mạo để mở tài khoản phục vụ mục đích lừa đảo, chuyển tiền đánh bạc qua mạng mà không bị phát hiện.', 'High', 'Xác thực sinh trắc học khuôn mặt và dữ liệu căn cước công dân gắn chip', 'Bắt buộc đối chiếu sinh trắc học (NFC chip CCCD và quét khuôn mặt FaceMatch) theo Quyết định 2345/QĐ-NHNN trước khi kích hoạt giao dịch trực tuyến.', 'Preventive', 'Hàng ngày', 'Automated', 'Trích xuất log các tài khoản mở mới có tỷ lệ khớp sinh trắc học dưới ngưỡng cảnh báo; rà soát hồ sơ mở tài khoản cho tổ chức/doanh nghiệp mới thành lập dưới 3 tháng.', 'Hồ sơ mở tài khoản, log dữ liệu sinh trắc học hệ thống Core/eKYC, kết quả tra cứu cơ sở dữ liệu quốc gia về dân cư.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Công nghệ Thông tin & An ninh Thông tin', 'Quản lý Người dùng Đặc quyền (PAM)', 'Bảo vệ cơ sở dữ liệu Core Banking khỏi các hành vi can thiệp trái phép', 'Can thiệp trực tiếp vào Database sản xuất ngoài giờ làm việc không có phê duyệt', 'Quản trị viên hệ thống (DBA, DevOps) sử dụng quyền đặc quyền để sửa đổi số dư, tài khoản hoặc dữ liệu giao dịch trên database mà không qua ứng dụng.', 'Critical', 'Quản lý phiên truy cập đặc quyền (PAM) và giám sát câu lệnh SQL (DAM)', '100% truy cập vào database sản xuất phải thông qua hệ thống PAM có ghi lại video phiên làm việc (Session Recording); cảnh báo tức thì các lệnh UPDATE/DELETE trực tiếp.', 'Preventive', 'Liên tục', 'Automated', 'Trích xuất log audit trail của cơ sở dữ liệu Core Banking; đối chiếu tất cả các câu lệnh DDL/DML can thiệp trực tiếp vào DB trong kỳ kiểm toán với danh sách phiếu Change Ticket được duyệt.', 'Log hệ thống PAM, phiếu yêu cầu thay đổi (CR) được Hội đồng CAB duyệt, báo cáo rà soát định kỳ của CISO.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Công nghệ Thông tin & An ninh Thông tin', 'Quản trị Vòng đời Tài khoản (IAM)', 'Đảm bảo chỉ người dùng đang công tác mới có quyền truy cập hệ thống ngân hàng', 'Không thu hồi tài khoản của nhân viên đã nghỉ việc hoặc chuyển đổi vị trí công tác', 'Nhân viên đã nghỉ việc vẫn còn tài khoản hoạt động trên Active Directory, Core Banking, VPN hoặc Email, tạo lỗ hổng cho rò rỉ dữ liệu khách hàng.', 'High', 'Tự động đồng bộ trạng thái nhân sự từ phần mềm HRM sang IAM và Active Directory', 'Khi phòng Nhân sự cập nhật ngày thôi việc trên HRM, hệ thống IAM tự động khóa tài khoản AD và thu hồi toàn bộ quyền truy cập ứng dụng trong vòng 2 giờ.', 'Preventive', 'Hàng ngày', 'Automated', 'Lấy danh sách 100% nhân viên thôi việc trong 6 tháng qua từ Khối Nhân sự; đối chiếu thời điểm thôi việc với thời điểm disable tài khoản trên AD, Core Banking và VPN.', 'Danh sách nhân sự thôi việc, log thu hồi tài khoản trên Active Directory và hệ thống IAM, báo cáo rà soát tài khoản định kỳ.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Công nghệ Thông tin & An ninh Thông tin', 'Sao lưu Dữ liệu & Diễn tập Thảm họa (DRP)', 'Đảm bảo tính liên tục của hoạt động ngân hàng khi xảy ra sự cố thiên tai/hỏng hóc', 'Bản sao lưu dữ liệu bị lỗi, không thể phục hồi hoặc không đạt mục tiêu RTO/RPO', 'Hệ thống Core Banking gặp sự cố nhưng bản sao lưu dữ liệu bị hỏng, hoặc thời gian chuyển đổi sang trung tâm dữ liệu dự phòng vượt quá thời gian cam kết.', 'High', 'Sao lưu tự động hàng ngày theo mô hình 3-2-1 và diễn tập khôi phục định kỳ', 'Thực hiện sao lưu Full hàng tuần và Incremental hàng ngày, lưu trữ bản sao ngoài trung tâm (Offsite); diễn tập chuyển đổi hoạt động sang DC dự phòng tối thiểu 1 lần/năm.', 'Detective', 'Hàng năm', 'IT-Dependent Manual', 'Kiểm tra nhật ký sao lưu tự động và biên bản thử nghiệm phục hồi bản backup gần nhất; đánh giá kết quả diễn tập chuyển đổi thảm họa (Disaster Recovery Drill) gần nhất.', 'Báo cáo kết quả diễn tập DRP, log sao lưu cơ sở dữ liệu hàng ngày, biên bản nghiệm thu chuyển đổi hệ thống trung tâm dữ liệu thứ 2.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Phòng chống Rửa tiền & Tuân thủ (AML/CFT)', 'Sàng lọc Danh sách Đen & Danh sách Trừng phạt', 'Ngăn chặn các giao dịch liên quan đến rửa tiền, tài trợ khủng bố và cấm vận', 'Bỏ sót khách hàng thuộc Danh sách Đen (Blacklist), Sanctions List hoặc PEP', 'Hệ thống không cập nhật danh sách cảnh báo hoặc cán bộ bỏ qua cảnh báo trùng khớp, dẫn đến thực hiện giao dịch cho đối tượng bị trừng phạt quốc tế.', 'Critical', 'Sàng lọc tự động (Sanction Screening) thời gian thực và cập nhật dữ liệu hàng ngày', 'Tất cả khách hàng mở mới và các giao dịch chuyển tiền quốc tế/trong nước phải được lọc tự động qua cơ sở dữ liệu cảnh báo; tự động chặn giao dịch khi độ trùng khớp trên 85%.', 'Preventive', 'Liên tục', 'Automated', 'Kiểm tra phiên bản dữ liệu Sanctions/PEP đang vận hành trên hệ thống AML; thực hiện test case giả lập thông tin cá nhân trong Blacklist để kiểm tra phản ứng của hệ thống; rà soát hồ sơ giải trình False Positive.', 'Báo cáo cấu hình hệ thống AML, biên bản cập nhật dữ liệu Sanctions hàng ngày, hồ sơ thẩm tra các giao dịch bị chặn.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Phòng chống Rửa tiền & Tuân thủ (AML/CFT)', 'Báo cáo Giao dịch Giá trị lớn (CTR) & Giao dịch Đáng ngờ (STR)', 'Tuân thủ nghĩa vụ báo cáo phòng chống rửa tiền theo Luật PCRT và quy định của NHNN', 'Báo cáo chậm trễ hoặc bỏ sót giao dịch có giá trị lớn và giao dịch đáng ngờ', 'Các giao dịch tiền mặt từ 400 triệu đồng trở lên hoặc giao dịch có dấu hiệu bất thường không được báo cáo cho Cục Phòng chống Rửa tiền - NHNN theo luật định.', 'High', 'Tự động trích xuất báo cáo CTR và kịch bản giám sát giao dịch bất thường', 'Hệ thống AML tự động tổng hợp dữ liệu giao dịch tiền mặt đủ ngưỡng để gửi báo cáo CTR; các kịch bản hành vi bất thường tự động phát sinh cảnh báo cho chuyên viên Compliance xử lý trong 48 giờ.', 'Detective', 'Hàng ngày', 'Automated', 'Trích xuất toàn bộ giao dịch tiền mặt từ 400 triệu đồng trong 3 tháng; đối chiếu với danh sách các giao dịch đã nộp cho NHNN; kiểm tra thời hạn gửi báo cáo STR của các case đã phân tích.', 'Báo cáo CTR/STR nộp NHNN, thông báo tiếp nhận điện tử của Cục PCRT, hồ sơ phân tích giao dịch đáng ngờ nội bộ.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Quản trị Kế toán & Báo cáo Tài chính', 'Phân loại Nợ & Trích lập Dự phòng Rủi ro', 'Phản ánh trung thực chất lượng tín dụng và lợi nhuận của ngân hàng', 'Phân loại sai nhóm nợ hoặc trích lập thiếu dự phòng rủi ro tín dụng', 'Chi nhánh hoặc cán bộ điều chỉnh nhóm nợ thủ công để giảm chi phí trích lập dự phòng theo Thông tư 11/2021/TT-NHNN nhằm đạt chỉ tiêu KPI.', 'Critical', 'Phân loại nợ tự động theo tiêu chí định lượng và kết quả tra cứu CIC định kỳ', 'Hệ thống tự động nhảy nhóm nợ theo số ngày quá hạn và đồng bộ nhóm nợ cao nhất trên toàn hệ thống TCTD theo dữ liệu CIC hàng tháng; Kế toán trưởng phê duyệt trích lập.', 'Preventive', 'Hàng tháng', 'Automated', 'Chạy lại công thức trích lập dự phòng cụ thể và chung độc lập trên toàn bộ danh mục cho vay cuối quý; đối chiếu nhóm nợ ngân hàng với nhóm nợ trên CIC của 50 khách hàng có dư nợ lớn nhất.', 'Bảng tính trích lập dự phòng rủi ro tín dụng, báo cáo đối chiếu CIC định kỳ, chứng từ hạch toán chi phí dự phòng.', 'KTNB_HoiSo', NOW(), NOW());
INSERT INTO risk_control_matrix ("processName", "subProcess", "businessObjective", "riskName", "riskDescription", "inherentRiskScore", "controlName", "controlDescription", "controlType", "controlFrequency", "controlAutomation", "testProcedure", "expectedEvidence", "ownerTeam", "createdAt", "updatedAt") VALUES ('Quản trị Kế toán & Báo cáo Tài chính', 'Quản lý Chi phí Hoạt động & Mua sắm Tài sản', 'Đảm bảo chi phí được phê duyệt đúng thẩm quyền và hạch toán đúng kỳ kế toán', 'Hạch toán chi phí không có đầy đủ hóa đơn hợp lệ hoặc chi vượt hạn mức ngân sách', 'Thanh toán chi phí sửa chữa, tiếp khách, mua sắm không có hóa đơn điện tử hợp pháp hoặc vượt ngân sách phân bổ nhưng không qua phê duyệt bổ sung.', 'Medium', 'Kiểm soát hạn mức ngân sách tự động trên ERP và kiểm tra hóa đơn điện tử', 'Hệ thống tự động chặn lệnh thanh toán khi chi phí vượt hạn mức ngân sách được duyệt; kế toán thanh toán kiểm tra mã tra cứu hóa đơn trên cổng cơ quan Thuế.', 'Preventive', 'Hàng ngày', 'IT-Dependent Manual', 'Chọn mẫu 20 món thanh toán chi phí lớn trong kỳ; kiểm tra tờ trình phê duyệt thẩm quyền, hợp đồng, biên bản nghiệm thu và tra cứu tính hợp lệ của hóa đơn VAT trên cổng Thuế.', 'Hóa đơn điện tử có mã cơ quan Thuế, tờ trình phê duyệt chi, hợp đồng kinh tế, phiếu chi/ủy nhiệm chi.', 'KTNB_HoiSo', NOW(), NOW());
